create extension if not exists pgcrypto;
create type business_unit as enum ('KY_OPRY','CCP','SHARED');
create type record_status as enum ('OPEN','WAITING','IN_PROGRESS','COMPLETE','ARCHIVED');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role text default 'admin', created_at timestamptz default now());
create table artists (id uuid primary key default gen_random_uuid(), name text not null, aliases text[] default '{}', genres text[] default '{}', spotify_url text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table venues (id uuid primary key default gen_random_uuid(), name text not null, address text, capacity integer, capacity_status text, notes text, created_at timestamptz default now());
create table events (id uuid primary key default gen_random_uuid(), business_unit business_unit not null default 'KY_OPRY', title text not null, artist_id uuid references artists(id), venue_id uuid references venues(id), starts_at timestamptz, doors_at timestamptz, stage text, visibility text default 'PRIVATE', ticketing_system text, external_source text, external_id text, tickets_sold integer, ticket_revenue numeric(12,2), last_refreshed_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table tasks (id uuid primary key default gen_random_uuid(), title text not null, description text, business_unit business_unit not null default 'SHARED', category text, task_type text, status record_status default 'OPEN', priority text default 'Normal', owner_id uuid references profiles(id), waiting_on text, due_at timestamptz, event_id uuid references events(id) on delete set null, artist_id uuid references artists(id) on delete set null, source_rule_id text, execution_system text, deep_link_target text, next_action text, completion_evidence text, source_document text, completed_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table notes (id uuid primary key default gen_random_uuid(), body text not null, business_unit business_unit default 'SHARED', event_id uuid references events(id), artist_id uuid references artists(id), visibility text default 'PRIVATE', created_by uuid references profiles(id), created_at timestamptz default now());
create table ideas (id uuid primary key default gen_random_uuid(), body text not null, source text default 'RACHEL', business_unit business_unit default 'SHARED', category text, objective text, status text default 'NEW', event_id uuid references events(id), artist_id uuid references artists(id), add_to_wednesday boolean default false, created_by uuid references profiles(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table meeting_items (id uuid primary key default gen_random_uuid(), meeting_date date, item_type text, title text not null, detail text, business_unit business_unit default 'SHARED', event_id uuid references events(id), artist_id uuid references artists(id), status text default 'OPEN', owner text, decision text, next_step text, created_at timestamptz default now());
create table content_ideas (id uuid primary key default gen_random_uuid(), business_unit business_unit not null, title text not null, objective text, pillar text, platform text, format text, hook text, cta text, audience text, status text default 'IDEA', event_id uuid references events(id), artist_id uuid references artists(id), publish_at timestamptz, source text, performance jsonb default '{}'::jsonb, lessons text, created_at timestamptz default now());
create table audience_suggestions (id uuid primary key default gen_random_uuid(), artist_or_event text not null, event_type text, buy_intent text, ticket_count text, price_comfort text, postal_code text, comment text, email text, phone text, email_opt_in boolean default false, sms_opt_in boolean default false, created_at timestamptz default now());
create table documents (id uuid primary key default gen_random_uuid(), title text not null, document_type text, storage_path text, business_unit business_unit default 'SHARED', event_id uuid references events(id), artist_id uuid references artists(id), source text, version text, visibility text default 'PRIVATE', created_at timestamptz default now());
create table change_log (id uuid primary key default gen_random_uuid(), entity_type text, entity_id uuid, business_unit business_unit default 'SHARED', what_changed text not null, before_value jsonb, after_value jsonb, reason text, goal text, approved_by text, expected_result text, review_at timestamptz, actual_result text, outcome text, created_by uuid references profiles(id), created_at timestamptz default now());
create table time_entries (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), started_at timestamptz not null, ended_at timestamptz, department text, business_unit business_unit default 'SHARED', event_id uuid references events(id), task_id uuid references tasks(id), note text, manual boolean default false, created_at timestamptz default now());
create table communications (id uuid primary key default gen_random_uuid(), account text, provider text default 'gmail', external_thread_id text, external_message_id text, subject text, from_address text, to_addresses text[], received_at timestamptz, state text, event_id uuid references events(id), artist_id uuid references artists(id), business_unit business_unit default 'SHARED', needs_reply boolean default false, followup_at timestamptz, source_payload jsonb, created_at timestamptz default now());
create table integration_sync_status (id uuid primary key default gen_random_uuid(), system text unique not null, business_unit business_unit default 'SHARED', status text, last_success_at timestamptz, last_attempt_at timestamptz, error text, metadata jsonb default '{}'::jsonb);
create table data_quality_issues (id uuid primary key default gen_random_uuid(), title text not null, severity text, status text default 'OPEN', detail text, affected_entity text, source_refs text[], created_at timestamptz default now(), resolved_at timestamptz);
create table requirements_registry (id text primary key, area text not null, requirement text not null, status text not null, source text, notes text, updated_at timestamptz default now());

alter table profiles enable row level security; alter table artists enable row level security; alter table venues enable row level security; alter table events enable row level security; alter table tasks enable row level security; alter table notes enable row level security; alter table ideas enable row level security; alter table meeting_items enable row level security; alter table content_ideas enable row level security; alter table documents enable row level security; alter table change_log enable row level security; alter table time_entries enable row level security; alter table communications enable row level security; alter table integration_sync_status enable row level security; alter table data_quality_issues enable row level security; alter table requirements_registry enable row level security;
-- Rachel-only v1: authenticated users can use private ops tables. Tighten to role-based policies before adding staff accounts.
do $$ declare t text; begin foreach t in array array['profiles','artists','venues','events','tasks','notes','ideas','meeting_items','content_ideas','documents','change_log','time_entries','communications','integration_sync_status','data_quality_issues','requirements_registry'] loop execute format('create policy "authenticated full access" on %I for all to authenticated using (true) with check (true)',t); end loop; end $$;
-- Public suggestion box: insert only; no public reads.
alter table audience_suggestions enable row level security;
create policy "public can submit suggestions" on audience_suggestions for insert to anon with check (true);
create policy "authenticated can manage suggestions" on audience_suggestions for all to authenticated using (true) with check (true);
